"""Trusted enterprise layout registry. User templates select layouts, never execute HTML."""
import re

LAYOUTS = {'classic': '简约名片', 'scenic': '全景展示', 'editorial': '画册展示', 'poster': '品牌海报'}
TEMPLATES = {
    'gallery': {'name': '画册展示', 'layout': 'editorial', 'accent': '#34675b'},
    'poster': {'name': '品牌海报', 'layout': 'poster', 'accent': '#aa5937'},
}

CSS = '''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#faf9f6;color:#26332f;font:16px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}a{color:inherit}header,main,footer{max-width:1160px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;gap:24px;align-items:center;border-bottom:1px solid #ddd8ce}header .logo{font-size:20px;font-weight:750;text-decoration:none;overflow-wrap:anywhere}nav{display:flex;gap:22px;flex-shrink:0}nav a{text-decoration:none;font-size:14px}h1{font-size:clamp(34px,6vw,68px);line-height:1.18;letter-spacing:-1px;margin:20px 0}h2{font-size:26px;line-height:1.4}h3{font-size:19px;line-height:1.5}p{overflow-wrap:anywhere}.eyebrow{color:var(--accent);font-size:13px;letter-spacing:2px}.muted,small,.notice{color:#6e766f;font-size:13px}.notice{padding:12px 0}.section{padding:40px 0;border-bottom:1px solid #e2e4dc}.module-content{min-width:0}.facts,.card p{white-space:pre-wrap;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:20px;margin:24px 0}.card{background:white;border:1px solid #dfe3d9;border-radius:14px;padding:26px}.card h3{margin-top:0}.contact{background:#ecefe6;padding:32px;border-radius:16px;margin-top:36px}.cover{width:100%;height:440px;object-fit:cover;border-radius:16px;display:block}.site-hero{padding:42px 0 18px}.hero-copy{max-width:850px}.photo-pair{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:24px 0}.photo-pair:has(figure:only-child){grid-template-columns:1fr}.photo-pair img{width:100%;height:260px;object-fit:cover;border-radius:14px}.photo-pair figure{margin:0}.photo-pair figcaption{font-size:12px;color:#6e766f;margin-top:8px}details{padding:14px 0}summary{cursor:pointer}form{display:flex;gap:12px;flex-wrap:wrap}textarea{width:100%;font:inherit;padding:12px;border:1px solid #cbd3ca;border-radius:8px;resize:vertical}button{font:inherit;border:0;border-radius:8px;background:var(--accent);color:white;padding:10px 20px;cursor:pointer}footer{font-size:12px;color:#737a73;border-top:1px solid #ddd8ce;margin-top:50px;display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap}.layout-scenic{background:#edf3ef}.layout-scenic .site-hero{display:flex;flex-direction:column;align-items:center;text-align:center;padding:45px 0 0;gap:20px}.layout-scenic .hero-copy{max-width:900px}.layout-scenic .cover{height:480px;border-radius:180px 180px 14px 14px}.layout-scenic .section{display:grid;grid-template-columns:220px minmax(0,1fr);gap:32px}.layout-scenic .section>h2{color:var(--accent)}.layout-scenic .card{border:0;box-shadow:0 12px 30px #2447340a}.layout-scenic .photo-pair img{height:300px;border-radius:6px}.layout-scenic .contact{background:#dce8df}.layout-editorial{background:#f5f2eb}.layout-editorial main{max-width:1240px}.layout-editorial .site-hero{display:grid;grid-template-columns:1fr 1.1fr;align-items:center;gap:50px;padding:54px 0}.layout-editorial .site-hero:not(:has(.cover)){display:block;border-left:6px solid var(--accent);padding:28px 36px;background:#ede8dc}.layout-editorial .section{display:grid;grid-template-columns:180px minmax(0,1fr);gap:36px}.layout-editorial .section>h2{font-family:Georgia,"Songti SC",serif;font-weight:500}.layout-editorial h1{font-family:Georgia,"Songti SC",serif;font-weight:500}.layout-editorial .cover{height:520px;border-radius:160px 160px 12px 12px}.layout-editorial .card{background:transparent;border:0;border-top:2px solid var(--accent);border-radius:0;padding:24px 0}.layout-editorial .photo-pair img{height:350px;border-radius:4px}.layout-poster{background:#161e21;color:#f8f5ec}.layout-poster header,.layout-poster footer{border-color:#354044}.layout-poster .site-hero{position:relative;min-height:530px;display:flex;align-items:flex-end;padding:45px;isolation:isolate;overflow:hidden;border-radius:20px;margin-top:24px;background:#273538}.layout-poster .site-hero .cover{position:absolute;inset:0;width:100%;height:100%;z-index:-2;border-radius:0}.layout-poster .site-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.85),rgba(0,0,0,.08));z-index:-1}.layout-poster .hero-copy{max-width:800px}.layout-poster .eyebrow{color:#f1c7a9}.layout-poster .muted,.layout-poster small,.layout-poster .notice,.layout-poster footer{color:#b9c3be}.layout-poster .card{background:#202b2f;border-color:#354044}.layout-poster .section{border-color:#354044}.layout-poster .contact{background:#263539}.layout-poster .photo-pair img{height:320px}.layout-poster .photo-pair figcaption{color:#b9c3be}@media(max-width:650px){.layout-scenic .section,.layout-editorial .section{grid-template-columns:1fr;gap:8px}.layout-scenic .cover{height:300px}.layout-scenic .photo-pair img{height:180px}header,main,footer{padding:18px}header{align-items:flex-start;flex-wrap:wrap}nav{gap:18px}.site-hero{padding-top:25px}.cover{height:290px}.photo-pair{gap:12px}.photo-pair img{height:160px}.section{padding:28px 0}.layout-editorial .site-hero{grid-template-columns:1fr;gap:20px;padding:28px 0}.layout-editorial .cover{height:350px}.layout-editorial .photo-pair img{height:190px}.layout-poster .site-hero{min-height:440px;padding:25px}.layout-poster .photo-pair img{height:180px}.contact{padding:22px}h1{overflow-wrap:anywhere}}
'''


def document(title, body, path, description, schema, name, layout, accent, preview, extra, escape):
    import json
    e=escape
    layout=layout if layout in LAYOUTS else 'classic'
    accent=accent if re.fullmatch(r'#[0-9a-fA-F]{6}',accent or '') else '#c05929'
    structured=json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')
    canonical='https://campfire.dawoai.com'+path
    home_path='/'.join(path.split('/')[:3])
    intro_link='#description' if path==home_path else home_path+'#description'
    return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+'</title><meta name="description" content="'+e(description)+'"><link rel="canonical" href="'+e(canonical)+'">'+('<meta name="robots" content="noindex,nofollow">' if preview else '')+'<style>'+CSS+'</style><script type="application/ld+json">'+structured+'</script></head><body class="layout-'+layout+'" style="--accent:'+accent+'"><header><a class="logo" href="'+e(home_path)+'">'+e(name)+'</a><nav><a href="'+e(intro_link)+'">企业介绍</a><a href="#contact">联系咨询</a></nav></header><main>'+body+'</main><footer><span>'+e(name)+' · 信息由企业维护</span><span>主页技术支持：<a href="https://campfire.dawoai.com/">营火AI</a></span></footer>'+extra+'</body></html>'
